      context "#make_request" do
        test "certain headers are always present" do
          path = "/test"

          request_headers = T.let(nil, T.nilable(T::Hash[String, T.untyped]))
          stub_capi_connection do |stub|
            stub.post(path) do |env|
              request_headers = env.request_headers
              [200, {}, ""]
            end
          end

          CopilotApiClient
            .new(user: @user)
            .send(:make_request, method: :post, path:)

          request_headers = T.must(request_headers)
          assert_equal(CopilotAPI::COPILOT_CHAT_INTEGRATION_ID, request_headers["Copilot-Integration-Id"])
          assert_equal(@user.id, request_headers[CopilotAPI::GITHUB_USER_HEADER])
        end

        context "when a decrypted token is provided" do
          test 'an Authorization header with "Bearer" is present' do
            path = "/test"

            request_headers = T.let(nil, T.nilable(T::Hash[String, T.untyped]))
            stub_capi_connection do |stub|
              stub.post(path) do |env|
                request_headers = env.request_headers
                [200, {}, ""]
              end
            end

            pat = Copilot::DecryptedToken.from("token")
            CopilotApiClient.new(token: pat, user: @user).send(:make_request, method: :post, path:)

            request_headers = T.must(request_headers)
            assert_equal("Bearer #{pat}", request_headers["Authorization"])
            assert_equal(CopilotAPI::COPILOT_CHAT_INTEGRATION_ID, request_headers["Copilot-Integration-Id"])
            assert_equal(@user.id, request_headers[CopilotAPI::GITHUB_USER_HEADER])
          end
        end

        context "when a Copilot::EncryptedToken token is provided" do
          test 'an Authorization header with "GitHub-Bearer" is present' do
            path = "/test"

            request_headers = T.let(nil, T.nilable(T::Hash[String, T.untyped]))
            stub_capi_connection do |stub|
              stub.post(path) do |env|
                request_headers = env.request_headers
                [200, {}, ""]
              end
            end

            token = Copilot::EncryptedToken.from("test")
            CopilotApiClient.new(token:, user: @user).send(:make_request, method: :post, path:)

            request_headers = T.must(request_headers)
            assert_equal("GitHub-Bearer #{token}", request_headers["Authorization"])
            assert_equal(CopilotAPI::COPILOT_CHAT_INTEGRATION_ID, request_headers["Copilot-Integration-Id"])
            assert_equal(@user.id, request_headers[CopilotAPI::GITHUB_USER_HEADER])
          end
        end
      end

      sig { params(block: T.proc.params(stub: Faraday::Adapter::Test::Stubs).void).void }
      def stub_capi_connection(&block)
        faraday_stub = GitHub::FaradayClient::Internal.new do |f|
          f.adapter :test do |stub|
            block.call(stub)
          end
        end
        CopilotApiClient.any_instance.stubs(:connection).returns(faraday_stub)
      end
    end
